    22→/**
    23→ * map 범용 사전. CharSequence : CharSequence[] pair이다. 만약 value에 Object[]를 사용하길
    24→ * 원한다면 custom dictionary를 사용한다.
    25→ */
    26→public class MapDictionary extends SourceDictionary<Object> {
    27→
    28→	protected Map<CharSequence, CharSequence[]> map;
    29→
    30→	public MapDictionary() {
    31→		this(false);
    32→	}
    33→
    34→	public MapDictionary(boolean ignoreCase) {
    35→		super(ignoreCase, null, 0, null, ProductNameDictionary.Type.MAP);
    36→		map = new HashMap<>();
    37→	}
    38→
    39→	public MapDictionary(Map<CharSequence, CharSequence[]> map, boolean ignoreCase, String label, int seq, String tokenType, ProductNameDictionary.Type type) {
    40→		super(ignoreCase, label, seq, tokenType, type);
    41→		this.map = map;
    42→	}
    43→
    44→	public MapDictionary(File file, boolean ignoreCase, String label, int seq, String tokenType, ProductNameDictionary.Type type) {
    45→		super(ignoreCase, label, seq, tokenType, type);
    46→		if (!file.exists()) {
    47→			map = new HashMap<>();
    48→			logger.error("사전파일이 존재하지 않습니다. file={}", file.getAbsolutePath());
    49→			return;
    50→		}
    51→		InputStream is = null;
    52→		try {
    53→			is = new FileInputStream(file);
    54→			readFrom(is);
    55→		} catch (IOException e) {
    56→			logger.error("", e);
    57→		} finally {
    58→			try { is.close(); } catch (Exception ignore) { }
    59→		}
    60→	}
    61→
    62→	public MapDictionary(InputStream is, boolean ignoreCase, String label, int seq, String tokenType, ProductNameDictionary.Type type) {
    63→		super(ignoreCase, label, seq, tokenType, type);
    64→		try {
    65→			readFrom(is);
    66→		} catch (IOException e) {
    67→			logger.error("", e);
    68→		}
    69→	}
    70→
    71→	@Override
    72→	public void addEntry(CharSequence keyword, Object[] values, List<Object> columnList) {
    73→		if (keyword == null) { return; }
    74→		if (values == null) { return; }
    75→		CharVector cv = new CharVector(String.valueOf(keyword).trim(), ignoreCase);
    76→		if (cv.length() == 0) { return; }
    77→		CharSequence[] list = new CharSequence[values.length];
    78→		for (int inx = 0; inx < values.length; inx++) {
    79→			list[inx] = new CharVector(String.valueOf(values[inx]), ignoreCase);
    80→		}
    81→		map.put(cv.removeWhitespaces(), list);
    82→	}
    83→
    84→	public Map<CharSequence, CharSequence[]> getUnmodifiableMap() {
    85→		return Collections.unmodifiableMap(map);
    86→	}
    87→
    88→	public Map<CharSequence, CharSequence[]> map() {
    89→		return map;
    90→	}
    91→
    92→	public void setMap(Map<CharSequence, CharSequence[]> map) {
    93→		this.map = map;
    94→	}
    95→
    96→	public boolean containsKey(CharSequence key) {
    97→		return map.containsKey(key);
    98→	}
    99→
   100→	public CharSequence[] get(CharSequence key) {
   101→		return map.get(key);
   102→	}
   103→
   104→	@Override
   105→	@SuppressWarnings("resource")
   106→	public void writeTo(OutputStream out) throws IOException {
   107→		if (!(out instanceof BufferedOutputStream)) {
   108→			try { out = new BufferedOutputStream(out); } catch (Exception ignore) { }
   109→		}
   110→		DataOutput output = new OutputStreamDataOutput(out);
   111→		Iterator<CharSequence> keySet = map.keySet().iterator();
   112→		// write size of map
   113→		output.writeVInt(map.size());
   114→		// write key and value map
   115→		for (; keySet.hasNext();) {
   116→			// write key
   117→			CharVector key = CharVector.valueOf(keySet.next());
   118→			output.writeUString(key.array(), key.offset(), key.length());
   119→			// write values
   120→			CharSequence[] values = map.get(key);
   121→			output.writeVInt(values.length);
   122→			for (CharSequence v : values) {
   123→				CharVector value = CharVector.valueOf(v);
   124→				output.writeUString(value.array(), value.offset(), value.length());
   125→			}
   126→		}
   127→		try { out.flush(); } catch (Exception ignore) { }
   128→	}
   129→
   130→	@Override
   131→	@SuppressWarnings("resource")
   132→	public void readFrom(InputStream in) throws IOException {
   133→		if (!(in instanceof BufferedInputStream)) {
   134→			try { in = new BufferedInputStream(in); } catch (Exception ignore) { }
   135→		}
   136→		DataInput input = new InputStreamDataInput(in);
   137→		map = new HashMap<>();
   138→		int size = input.readVInt();
   139→		for (int entryInx = 0; entryInx < size; entryInx++) {
   140→			CharSequence key = new CharVector(input.readUString(), ignoreCase);
   141→
   142→			int valueLength = input.readVInt();
   143→
   144→			CharSequence[] values = new CharSequence[valueLength];
   145→
   146→			for (int valueInx = 0; valueInx < valueLength; valueInx++) {
   147→				values[valueInx] = new CharVector(input.readUString(), ignoreCase);
   148→			}
   149→			map.put(key, values);
   150→		}
   151→	}
   152→
   153→	@Override
   154→	public void addSourceLineEntry(CharSequence line) {
   155→		if (line == null) { return; }
   156→		String[] kv = String.valueOf(line).split("\t");
   157→		if (kv.length == 1) {
   158→			String value = kv[0].trim();
   159→			addEntry(null, new String[] { value }, null);
   160→		} else if (kv.length == 2) {
   161→			String keyword = kv[0].trim();
   162→			String value = kv[1].trim();
   163→			addEntry(keyword, new String[] { value }, null);
   164→		}
   165→	}
   166→
   167→	@Override
   168→	public void reload(Object object) throws IllegalArgumentException {
   169→		if (object != null && object instanceof MapDictionary) {
   170→			MapDictionary mapDictionary = (MapDictionary) object;
   171→			this.map = mapDictionary.map();
   172→		} else {
   173→			throw new IllegalArgumentException("Reload dictionary argument error. argument = " + object);
   174→		}
   175→	}
   176→}
