    75→		List<CharSequence> list = new ArrayList<>(4);
    76→		CharVector mainWord = null;
    77→		if (keyword != null) {
    78→			mainWord = new CharVector(String.valueOf(keyword).trim(), ignoreCase);
    79→			if (mainWord.length() > 0) {
    80→				wordSet.add(mainWord);
    81→				if (mainWord.hasWhitespaces()) {
    82→					for (CharSequence w : CharVector.splitByWhitespace(mainWord)) {
    83→						wordSet.add(w);
