    94→		dedupSynonym(synonyms);
    95→		for (int k = 0; k < synonyms.length; k++) {
    96→			String synonym = synonyms[k].trim();
    97→			if (synonym.length() > 0) {
    98→				CharVector word = new CharVector(synonym, ignoreCase);
    99→				list.add(word);
   100→				wordSet.add(word);
   101→				if (word.hasWhitespaces()) {
   102→					for (CharSequence w : CharVector.splitByWhitespace(word)) {
