   120→					}
   121→				}
   122→				// 유사어사전 데이터에 대표단어와 동일한 단어가 여러개 있을경우, 최종리스트는 더 적어지게 되므로 전체 array
   123→				// 길이를 줄여준다.
   124→				if (idx < value.length) {
   125→					value = Arrays.copyOf(value, idx);
   126→				}
   127→
   128→				if (value.length > 0) {
   129→					CharSequence[] value2 = map.get(key);
   130→					if (value2 != null) {
   131→						// 이전값과 머징.
   132→						value2 = duplicateCharList(value2);
   133→						value = mergeSynonyms(value2, value);
   134→					}
   135→					map.put(key, value);
   136→					// 공백을 제거한 key도 하나더 만든다.
   137→					if (key.hasWhitespaces()) {
   138→						key = new CharVector(String.valueOf(key), ignoreCase).removeWhitespaces();
   139→						value2 = map.get(key);
   140→						if (value2 != null) {
   141→							// 이전값과 머징.
   142→							value2 = duplicateCharList(value2);
   143→							value = mergeSynonyms(value2, value);
   144→						}
   145→						map.put(key, value);
   146→					}
   147→					// logger.debug("유사어 양방향 {} >> {}", key, join(value));
   148→				}
   149→			}
   150→		} else {
   151→			// 단방향.
   152→			CharSequence[] value = new CharSequence[list.size()];
   153→			int idx = 0;
   154→			for (int j = 0; j < value.length; j++) {
   155→				CharSequence word = list.get(j);
   156→				if (!mainWord.equals(word)) {
   157→					// 다른것만 value로 넣는다.
   158→					value[idx++] = word;
   159→				}
   160→			}
   161→			if (idx < value.length) {
   162→				value = Arrays.copyOf(value, idx);
   163→			}
   164→			if (value.length > 0) {
   165→				CharSequence[] value2 = map.get(mainWord);
   166→				if (value2 != null) {
   167→					// 이전값과 머징.
   168→					value2 = duplicateCharList(value2);
   169→					value = mergeSynonyms(value2, value);
   170→				}
   171→				//
   172→				// 입력시 키워드는 공백제거.
   173→				//
   174→				map.put(mainWord, value);
   175→				// 공백이 포함되어 있다면, 제거한 단어도 함께 넣어준다.
   176→				if (mainWord.hasWhitespaces()) {
   177→					map.put(new CharVector(String.valueOf(mainWord), ignoreCase).removeWhitespaces(), value);
   178→				}
   179→				// logger.debug("유사어 단방향 {} >> {}", mainWord, join(value));
   180→			}
   181→		}
   182→	}
   183→
   184→	// 중복제거한다. 중복이 발견되면 "" 로 치환한다.
   185→	private void dedupSynonym(String[] list) {
   186→		if (list == null || list.length < 2) {
   187→			return;
   188→		}
   189→		for (int i = 0; i < list.length; i++) {
   190→			for (int j = i + 1; j < list.length; j++) {
   191→				if (list[j].length() != 0 && list[i].equals(list[j])) {
   192→					list[j] = "";
   193→				}
   194→			}
   195→		}
   196→		return;
   197→	}
   198→
   199→	private CharSequence[] mergeSynonyms(CharSequence[] value2, CharSequence[] value) {
   200→		int removedCount = 0;
   201→		for (int i = 0; i < value.length; i++) {
   202→			for (int j = i + 1; j < value2.length; j++) {
   203→				if (value2[j] != null && value[i].equals(value2[j])) {
   204→					value2[j] = null;
   205→					removedCount++;
   206→				}
   207→			}
   208→		}
   209→		int newSize = value2.length + value.length - removedCount;
   210→		CharSequence[] list = new CharSequence[newSize];
   211→		int i = 0;
   212→		for (CharSequence v : value2) {
   213→			if (v != null) {
   214→				list[i++] = v;
   215→			}
   216→		}
   217→		for (CharSequence v : value) {
   218→			if (v != null) {
   219→				list[i++] = v;
   220→			}
   221→		}
   222→		return list;
   223→	}
