   230→		}
   231→		super.writeTo(out);
   232→		DataOutput output = new OutputStreamDataOutput(out);
   233→		// write size of synonyms
   234→		output.writeVInt(wordSet.size());
   235→		// write synonyms
   236→		Iterator<CharSequence> synonymIter = wordSet.iterator();
   237→		for (; synonymIter.hasNext();) {
   238→			CharVector value = CharVector.valueOf(synonymIter.next());
   239→			output.writeUString(value.array(), value.offset(), value.length());
