   109→	public static void addSourceEntry(
   110→		Map<CharSequence, List<TagProb>> probMap,
   111→		String line, boolean ignoreCase) {
   112→		if (line.startsWith("#") || line.startsWith("//") || line.length() == 0) {
   113→			return;
   114→		}
   115→		String[] tmp = line.split("\t");
   116→		if (tmp.length != 3) { return; }
   117→
   118→		PosTag posTag = null;
   119→		if (tmp[1].startsWith("N")) {
   120→			posTag = PosTag.N;
   121→		} else if (tmp[1].startsWith("V")) {
   122→			posTag = PosTag.V;
   123→		} else if (tmp[1].startsWith("M")) {
   124→			posTag = PosTag.M;
   125→		} else if (tmp[1].startsWith("IC")) {
   126→			posTag = PosTag.IC;
   127→		} else if (tmp[1].startsWith("J")) {
   128→			posTag = PosTag.J;
   129→		} else if (tmp[1].startsWith("E")) {
   130→			posTag = PosTag.E;
   131→		} else if (tmp[1].startsWith("XPN")) {
   132→			posTag = PosTag.XPN;
   133→		} else {
   134→			return;
   135→		}
   136→		
   137→		CharVector key = new CharVector(tmp[0].trim());
   138→		if (ignoreCase) {
   139→			key.ignoreCase();
   140→		}
   141→		double prob = Double.parseDouble(tmp[2].trim());
   142→		if (key.length() == 1) {
   143→			// 한글자는 확률이 높아도 막는다.2014-2-3 swsong
   144→			if (posTag == PosTag.N) {
   145→				if (prob > -13) {
   146→					prob = TagProb.MIN_PROB;
   147→				}
   148→			} else {
   149→				// 명사가 아닌 한글자는 버린다.
   150→				return;
   151→			}
   152→		}
   153→		List<TagProb> tagProbList = probMap.get(key);
   154→		TagProb tagProb = new TagProb(posTag, prob);
   155→		if (tagProbList == null) {
   156→			tagProbList = new ArrayList<TagProb>(1);
   157→			probMap.put(key, tagProbList);
   158→			tagProbList.add(tagProb);
   159→		} else {
   160→			if (tagProbList.contains(tagProb)) {
   161→				for (int i = 0; i < tagProbList.size(); i++) {
   162→					TagProb tagProb2 = tagProbList.get(i);
   163→					if (tagProb2.posTag() == tagProb.posTag()) {
   164→						if (tagProb2.prob() < tagProb.prob()) {
   165→							tagProbList.remove(i);
   166→							tagProbList.add(tagProb);
   167→							break;
   168→						}
   169→					}
   170→				}
   171→			} else {
   172→				tagProbList.add(tagProb);
   173→			}
   174→		}
   175→	}
   176→
   177→	private void putAndReplaceProbMap(CharSequence key, TagProb tagProb) {
   178→		List<TagProb> tagProbList = probMap.get(key);
   179→		if (tagProbList == null) {
   180→			tagProbList = new ArrayList<TagProb>(1);
   181→			tagProbList.add(tagProb);
   182→			probMap.put(key, tagProbList);
   183→		} else {
   184→			boolean foundTag = false;
   185→			for (int i = 0; i < tagProbList.size(); i++) {
   186→				TagProb oldTagProb = tagProbList.get(i);
   187→				if (oldTagProb.equals(tagProb)) {
   188→					if (tagProb.prob() > oldTagProb.prob()) {
   189→						// 새로 셋팅할 tagprob가 더 크면 재 셋팅필요.
   190→						tagProbList.remove(i);
   191→					} else {
   192→						foundTag = true;
   193→					}
   194→					break;
   195→				}
   196→			}
   197→			if (!foundTag) {
   198→				tagProbList.add(tagProb);
   199→			}
   200→		}
   201→	}
